-- V20: isolate Camunda engine tables from application tables and public schema privileges.\n-- Existing public-schema engine tables require an explicit, reviewed migration; never silently fork history.\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM information_schema.tables\n    WHERE table_schema = 'public' AND table_name LIKE 'ACT\_%' ESCAPE '\'\n  ) THEN\n    RAISE EXCEPTION 'V20 blocked: Camunda tables exist in public; migrate them to schema camunda with a reviewed maintenance plan first';\n  END IF;\nEND $$;\nCREATE SCHEMA IF NOT EXISTS camunda;\nREVOKE CREATE ON SCHEMA public FROM app_user;\nGRANT USAGE, CREATE ON SCHEMA camunda TO app_user;